70	function getAboutHeroSloganElement(): HTMLElement | null {
71	  if (aboutHeroSloganElement?.isConnected) {
72	    return aboutHeroSloganElement;
73	  }
74	  aboutHeroSloganElement = document.querySelector<HTMLElement>(
75	    ABOUT_HERO_SLOGAN_SELECTOR,
76	  );
77	  return aboutHeroSloganElement;
78	}
