80	function getAboutJourneySurfaceElement(): HTMLElement | null {
81	  if (aboutJourneySurfaceElement?.isConnected) {
82	    return aboutJourneySurfaceElement;
83	  }
84	  aboutJourneySurfaceElement = document.querySelector<HTMLElement>(
85	    ABOUT_JOURNEY_SURFACE_SELECTOR,
86	  );
87	  return aboutJourneySurfaceElement;
