90	function setAboutHeroSloganSurfaceAlpha(progress: number): void {
91	  const element = getAboutHeroSloganElement();
92	  if (!element) return;
93	  const clampedProgress = Math.max(0, Math.min(1, progress));
94	  const alpha =
95	    ABOUT_HERO_SLOGAN_ALPHA_MIN +
96	    ABOUT_HERO_SLOGAN_ALPHA_SPAN * clampedProgress;
97	  element.style.setProperty(ABOUT_HERO_SLOGAN_ALPHA_PROPERTY, alpha.toFixed(4));
98	}
99	
100	function resetAboutHeroSloganSurfaceAlpha(): void {
101	  const element = getAboutHeroSloganElement();
102	  if (!element) return;
103	  element.style.setProperty(
