243	  readState(sheetId: AboutTheatreSheetId, position = 0): AboutTheatreValue {
244	    const sequence = this._sequenceBySheetId.get(sheetId);
245	    const object = this._objectBySheetId.get(sheetId);
246	    if (!sequence || !object)
247	      return pickAboutTheatreValue(cloneAboutSceneState(ABOUT_DEFAULT_SCENE_STATE));
248	    const previousPosition = sequence.position;
249	    sequence.position = this._clampPosition(
250	      position,
251	      this._lengthBySheetId.get(sheetId) ?? 0,
252	    );
253	    const state = mergeAboutTheatreValue(object.value);
254	    sequence.position = previousPosition;
255	    return pickAboutTheatreValue(state);
256	  }
