384	  private _startSheetAutoplay(
385	    engine: Engine,
386	    sheetId: AboutTheatreSheetId,
387	    rate: number,
388	  ): Promise<void> {
389	    return this._autoplayRuntime.startSheetAutoplay(engine, {
