406	  syncSceneToEngine(
407	    engine: Engine,
408	    sceneKey: AboutSceneSectionKey,
409	    progress: number,
410	  ): AboutSceneProgressState | null {
411	    const resolvedState = this.resolveSceneState(sceneKey, progress);
412	    const progressState = this.resolveSceneProgressState(sceneKey, progress);
413	    if (
414	      DEBUG_SCENE_KEYS.includes(sceneKey) &&
415	      shouldLogDebugBucket(
416	        debugSyncLogKeyByScene,
417	        sceneKey,
418	        "sync",
419	        progress,
420	        progressState?.sheetId ?? null,
421	      )
422	    ) {
423	      const range =
424	        progressState == null
425	          ? null
426	          : this._resolvePlaybackRange(
427	              progressState.sheetId,
428	              this._lengthBySheetId.get(progressState.sheetId) ?? 0,
429	            );
430	      const position =
431	        progressState == null || range == null
432	          ? null
433	          : range.start +
434	            (range.end - range.start) * this._clampPosition(progressState.localProgress, 1);
435	      Logger.info(CLASS, "syncSceneToEngine", `Applying about theatre scene ${sceneKey}.`, {
436	        sceneKey,
437	        progress,
438	        progressState,
439	        range,
440	        position,
441	        camera: resolvedState?.camera ?? null,
442	      });
443	    }
444	    this._rig.apply(
445	      engine,
446	      mergeAboutTheatreValue(resolvedState ?? pickAboutTheatreValue(ABOUT_DEFAULT_SCENE_STATE)),
447	    );
448	    return progressState;
449	  }
