468	  private _resolveSheetLength(
469	    sheetId: AboutTheatreSheetId,
470	    sequence: TheatreSequencePort,
471	  ): number {
472	    const directLength =
473	      typeof sequence.length === "number" ? sequence.length : null;
474	    if (
475	      directLength != null &&
476	      Number.isFinite(directLength) &&
477	      directLength > 0
478	    ) {
479	      return directLength;
480	    }
481	    const stateLength = this._readSheetLengthFromState(sheetId);
482	    if (stateLength > 0) return stateLength;
483	    return 0;
484	  }
