492	  private _resolveStep(
493	    step: AboutTheatrePlaybackStep,
494	  ): AboutResolvedTheatrePlaybackStep | null {
495	    const sequence = this._sequenceBySheetId.get(step.sheetId);
496	    if (!sequence) return null;
497	    const length = this._lengthBySheetId.get(step.sheetId) ?? 0;
498	    return {
499	      sheetId: step.sheetId,
500	      range: this._resolveConfiguredPlaybackRange(
501	        step.playbackRange,
502	        step.sheetId,
503	        length,
504	      ),
505	      progressRange: this._resolveProgressRange(step.progressRange),
506	    };
507	  }
