509	  private _resolveConfiguredPlaybackRange(
510	    configuredRange: AboutTheatrePlaybackRange | undefined,
511	    sheetId: AboutTheatreSheetId,
512	    length: number,
513	  ): AboutTheatrePlaybackRange {
514	    if (!configuredRange) {
515	      return this._resolvePlaybackRange(sheetId, length);
516	    }
517	    return {
518	      start: this._clampPosition(configuredRange.start, length),
519	      end: this._clampPosition(configuredRange.end, length),
520	    };
521	  }
522	
523	  private _resolveProgressRange(
524	    progressRange: AboutSceneProgressRange | undefined,
525	  ): AboutSceneProgressRange {
526	    if (!progressRange) {
527	      return { start: 0, end: 1 };
528	    }
529	    const start = this._clampPosition(progressRange.start, 1);
530	    const end = this._clampPosition(progressRange.end, 1);
531	    if (end <= start) {
532	      return { start, end: 1 };
533	    }
534	    return { start, end };
535	  }
536	
537	  private _isProgressWithinRange(
538	    progress: number,
539	    range: AboutSceneProgressRange,
540	  ): boolean {
541	    if (progress < range.start) return false;
542	    if (progress > range.end && range.end < 1) return false;
543	    return true;
544	  }
545	
546	  private _resolveLocalProgress(
547	    progress: number,
548	    range: AboutSceneProgressRange,
549	  ): number {
550	    const span = Math.max(range.end - range.start, Number.EPSILON);
551	    return this._clampPosition((progress - range.start) / span, 1);
552	  }
