432	  private _matchFromPrevious(): void {
433	    const currentIndex = ABOUT_THEATRE_SHEET_IDS.indexOf(this._authorSheetId);
434	    if (currentIndex <= 0) {
435	      this._renderStatus("NO PREVIOUS SHEET");
436	      return;
437	    }
438	    const previousSheetId = ABOUT_THEATRE_SHEET_IDS[currentIndex - 1];
439	    const previousObject = this._objectBySheetId.get(previousSheetId) ?? null;
440	    const previousSequence = this._sequenceBySheetId.get(previousSheetId) ?? null;
441	    const currentObject = this._currentObject;
442	    const currentSequence = this._sequenceBySheetId.get(this._authorSheetId) ?? null;
443	    if (!previousObject || !previousSequence || !currentObject || !currentSequence) {
444	      this._renderStatus("MATCH FAILED");
445	      return;
446	    }
447	
448	    const previousEndValues = this._readSheetEndValues(
449	      previousSheetId,
450	      previousObject,
451	      previousSequence,
452	    );
453	    if (!previousEndValues) {
454	      this._renderStatus("MATCH FAILED");
455	      return;
456	    }
457	
458	    this._writeMatchStartKeyframe(
459	      currentObject,
460	      currentSequence,
461	      previousEndValues,
462	    );
463	    this._applyState(previousEndValues);
464	    this._schedulePersistSaveFileSnapshot("MATCH SAVE FAILED");
465	    this._renderStatus(`MATCHED ${previousSheetId.toUpperCase()}`);
466	  }
