659	  private _normalizeSavedState(
660	    savedState: Record<string, unknown>,
661	  ): Record<string, unknown> {
662	    const migratedState = this._migrateLegacySheetState(savedState);
663	    const sheetsById = this._readRecord(migratedState.sheetsById);
664	    const cameraSheet = this._readRecord(sheetsById?.[PRIMARY_SHEET_ID]);
665	    const sequence = this._readRecord(cameraSheet?.sequence);
666	    const staticOverrides = this._readRecord(sequence?.staticOverrides);
667	    const objectsByKey = this._readRecord(staticOverrides?.byObject);
668	    const cameraObject = this._readRecord(
669	      objectsByKey?.[ABOUT_THEATRE_OBJECT_ID],
670	    );
671	
672	    if (cameraObject) {
673	      const mergedValues = mergeAboutSceneState(
674	        cameraObject as Partial<typeof ABOUT_DEFAULT_SCENE_STATE>,
675	      );
676	      Object.assign(cameraObject, pickAboutTheatreValue(mergedValues));
677	    }
678	
679	    const projectDefinition = this._readRecord(
680	      savedState.definitionVersion != null ? savedState : null,
681	    );
682	    if (projectDefinition && projectDefinition.addressesBySheetId) {
683	      return { ...migratedState, projectId: ABOUT_THEATRE_PROJECT_ID };
684	    }
685	
686	    return migratedState;
687	  }
688	
689	  private _migrateLegacySheetState(
690	    savedState: Record<string, unknown>,
691	  ): Record<string, unknown> {
692	    const sheetsById = this._readRecord(savedState.sheetsById);
693	    if (!sheetsById) return savedState;
694	
695	    const nextSheetsById: Record<string, unknown> = {};
696	    let didChange = false;
697	
698	    Object.entries(sheetsById).forEach(([sheetId, sheetState]) => {
699	      const mappedSheetId =
700	        LEGACY_ABOUT_SHEET_ID_MAP[sheetId as LegacyAboutSheetId] ?? sheetId;
701	      if (mappedSheetId !== sheetId) {
702	        didChange = true;
703	      }
704	      if ((ABOUT_THEATRE_SHEET_IDS as readonly string[]).includes(mappedSheetId)) {
705	        nextSheetsById[mappedSheetId] = sheetState;
706	        return;
707	      }
708	      didChange = true;
709	    });
710	
711	    if (!didChange) return savedState;
712	
713	    return {
714	      ...savedState,
715	      sheetsById: nextSheetsById,
716	    };
717	  }
718	
719	  private _readRecord(value: unknown): Record<string, unknown> | null {
720	    if (value == null || typeof value !== "object" || Array.isArray(value)) {
721	      return null;
722	    }
723	    return value as Record<string, unknown>;
724	  }
725	
726	  private _minimizeSaveFile(
727	    saveFile: Record<string, unknown>,
728	  ): Record<string, unknown> {
729	    const sheetsById = this._readRecord(saveFile.sheetsById);
730	    if (!sheetsById) return saveFile;
731	    const nextSheetsById: Record<string, unknown> = {};
732	    Object.entries(sheetsById).forEach(([sheetId, sheetState]) => {
733	      if (!this._isTheatreSheetId(sheetId)) return;
734	      const normalizedSheetState = this._normalizeSheetState(
735	        sheetState,
736	        sheetId,
737	      );
738	      if (!normalizedSheetState) return;
739	      nextSheetsById[sheetId] = normalizedSheetState;
740	    });
741	    return {
742	      ...saveFile,
743	      sheetsById: nextSheetsById,
744	    };
745	  }
746	
747	  private _normalizeSheetState(
748	    sheetState: unknown,
749	    sheetId: AboutTheatreSheetId,
750	  ): Record<string, unknown> | null {
751	    const sheetRecord = this._readRecord(sheetState);
752	    if (!sheetRecord) return null;
753	    if (this._sheetHasMeaningfulKeyframes(sheetRecord, sheetId)) {
754	      return sheetRecord;
755	    }
756	    return null;
757	  }
758	
759	  private _sheetHasMeaningfulKeyframes(
760	    sheetState: Record<string, unknown>,
761	    sheetId: AboutTheatreSheetId,
762	  ): boolean {
763	    const sequenceState = this._readRecord(sheetState.sequence);
764	    if (!sequenceState) return false;
765	    const tracksByObject = this._readRecord(sequenceState.tracksByObject);
766	    if (!tracksByObject) return false;
767	    const objectTracks = this._readRecord(tracksByObject[ABOUT_THEATRE_OBJECT_ID]);
768	    if (!objectTracks) return false;
769	    const trackData = this._readRecord(objectTracks.trackData);
770	    if (!trackData) return false;
771	    const sequence = this._sequenceBySheetId.get(sheetId);
772	    if (!sequence) return false;
773	    return Object.values(trackData).some((trackState) =>
774	      this._trackHasMeaningfulKeyframes(trackState, sequence),
775	    );
776	  }
777	
778	  private _trackHasMeaningfulKeyframes(
779	    trackState: unknown,
780	    sequence: TheatreSequencePort,
781	  ): boolean {
782	    const trackRecord = this._readRecord(trackState);
783	    if (!trackRecord) return false;
784	    const keyframes = trackRecord.keyframes;
785	    if (!Array.isArray(keyframes) || keyframes.length === 0) {
786	      return false;
787	    }
788	    const positions = keyframes
789	      .map((keyframe) => {
790	        const keyframeRecord = this._readRecord(keyframe);
791	        const position = keyframeRecord?.position;
792	        return typeof position === "number" && Number.isFinite(position)
793	          ? position
794	          : null;
795	      })
796	      .filter((position): position is number => position != null);
797	    return positions.length > 0;
798	  }
799	
800	  private _downloadSaveFile(raw: string, fileName: string): boolean {
801	    return TheatreStudioService.downloadFile(raw, { fileName });
802	  }
803	
804	  private _isReadableTheatreState(
805	    value: Record<string, unknown> | null,
806	  ): value is Record<string, unknown> {
807	    if (!value) return false;
808	    const sheetsById = value.sheetsById;
809	    if (
810	      sheetsById == null ||
811	      typeof sheetsById !== "object" ||
812	      Array.isArray(sheetsById)
813	    ) {
814	      return false;
815	    }
816	    return true;
817	  }
